import re,json
from pathlib import Path
sql=Path('docs/supabase/schema.sql').read_text()
purpose={'admin_users':'Asignación administrativa protegida; no editable desde formularios.','categories':'Catálogo de oficios. Se desactiva sin eliminar referencias.','parishes':'Catálogo territorial de La Guaira.','worker_profiles':'Identidad pública, servicios, experiencia y estado de publicación.','worker_service_areas':'Cobertura real del trabajador; relación muchos a muchos.','worker_photos':'Metadatos y rutas privadas del avatar y portafolio.','worker_testimonials':'Recomendaciones aportadas por el trabajador, sin verificación.','profile_moderation':'Ocultamiento administrativo independiente de la publicación.','moderation_events':'Registro de acciones administrativas.'}
meaning={'id':'Identificador único UUID.','user_id':'Cuenta de Supabase Auth con acceso administrativo.','granted_at':'Fecha de asignación del rol.','granted_by':'Usuario que asignó el rol; puede ser nulo al eliminar su cuenta.','name':'Nombre visible del catálogo.','slug':'Identificador legible para rutas y filtros.','is_active':'Disponible para nuevas selecciones.','sort_order':'Orden de presentación.','created_at':'Fecha de creación en UTC.','owner_id':'Usuario autenticado propietario; único por perfil.','public_name':'Nombre público del trabajador.','category_id':'Oficio principal; puede estar vacío en un borrador.','whatsapp_e164':'Número internacional validado; no almacenar contraseñas ni contactos de clientes.','location_parish_id':'Ubicación del trabajador; distinta de cobertura.','services_description':'Servicios y presentación; máximo 5.000 caracteres.','years_experience':'Opcional; entero de 0 a 80.','status':'draft, published o paused.','is_demo':'Marca reservada al sistema para datos ficticios.','updated_at':'Fecha de cambio; versión optimista para guardado.','published_at':'Fecha de publicación; la RPC establece el valor.','profile_id':'Perfil relacionado.','parish_id':'Parroquia donde presta servicio.','kind':'avatar o work.','position':'Orden: avatar 0; trabajo 1–6; testimonio 1–10.','storage_path':'Ruta única dentro del bucket privado worker-media.','alt_text':'Texto alternativo para accesibilidad.','recommender_name':'Nombre público del recomendante, aportado por el trabajador.','body':'Texto del testimonio; no es reseña verificada.','is_hidden':'true impide toda lectura pública del perfil.','reason':'Motivo interno de la acción administrativa.','updated_by':'Administrador que realizó el cambio.','actor_id':'Cuenta del administrador que ejecutó la acción.','action':'hide o restore.'}
models=[];rels=[]
for full,body in re.findall(r'create table (\w+\.\w+) \((.*?)\n\);',sql,re.S):
 name=full.split('.')[1];cols=[]
 for line in body.splitlines():
  line=line.strip().rstrip(',')
  m=re.match(r'([a-z0-9_]+) (uuid|text|boolean|integer|smallint|timestamptz|public\.[a-z_]+)(.*)',line)
  if not m:continue
  col,typ,rest=m.groups();ref=re.search(r'references ([\w.]+)\((\w+)\)',rest)
  if ref:rels.append({'from':full,'column':col,'to':ref[1],'target':ref[2],'cardinality':'N:1' if col!='owner_id' and full!='public.profile_moderation' else '0..1:1'})
  cols.append({'name':col,'type':typ,'nullable':not ('not null' in rest or 'primary key' in rest),'key':('PK' if 'primary key' in rest else 'FK' if ref else 'UNIQUE' if 'unique' in rest else ''),'rule':rest.strip(),'description':meaning.get(col,'Campo de negocio.')})
 if name=='worker_service_areas':
  for col in cols:col['nullable']=False;col['key']='PK + FK'
 models.append({'name':full,'purpose':purpose[name],'managed':False,'columns':cols})
managed=[('auth.users','Cuentas y credenciales administradas por Supabase Auth. Columnas relevantes, no diccionario completo del sistema.', [('id','uuid','PK','Identidad de la cuenta.'),('email','text','','Correo privado, no visible en el directorio.'),('encrypted_password','text','','Hash administrado por Auth; no consultar ni copiar al frontend.'),('email_confirmed_at','timestamptz','','Confirmación del correo.'),('created_at','timestamptz','','Fecha de registro.')]),('storage.objects','Objetos administrados por Supabase Storage; metadatos relevantes, no recrear la tabla.', [('id','uuid','PK','Identidad del objeto.'),('bucket_id','text','FK','Bucket worker-media.'),('name','text','','Ruta registrada en worker_photos.storage_path.'),('metadata','jsonb','','Metadatos del archivo; el backend verifica tamaño y contenido real.'),('created_at','timestamptz','','Fecha de subida.')]),('storage.buckets','Contenedores de Storage. Se configura un bucket privado; no recrear esta tabla.', [('id','text','PK','Identificador worker-media.'),('name','text','','Nombre del bucket.'),('public','boolean','','false para no exponer archivos por URL pública.'),('file_size_limit','bigint','','2.097.152 bytes.'),('allowed_mime_types','text[]','','image/jpeg, image/png, image/webp.')])]
for name,p,cols in managed:models.append({'name':name,'purpose':p,'managed':True,'columns':[{'name':n,'type':t,'key':k,'nullable':n!='id','rule':'Gestionado por Supabase','description':d} for n,t,k,d in cols]})
rels.extend([{'from':'storage.objects','column':'bucket_id','to':'storage.buckets','target':'id','cardinality':'N:1'},{'from':'public.worker_photos','column':'storage_path','to':'storage.objects','target':'name + bucket_id','cardinality':'Lógica, no FK SQL'}])
Path('docs/schema-data.js').write_text('const schemaModels = '+json.dumps(models,ensure_ascii=False,indent=2)+';\nconst schemaRelations = '+json.dumps(rels,ensure_ascii=False,indent=2)+';\n')
